#!/usr/bin/env bash
set -Eeuo pipefail
umask 027
[[ "$EUID" -eq 0 ]] || { echo "Run as root" >&2; exit 1; }
[[ -x /opt/auto-photo-ingest/venv/bin/auto-photo-ingest ]] || { echo "Existing installation not found" >&2; exit 1; }
work_dir="$(mktemp -d /root/auto-photo-upgrade.XXXXXX)"
cleanup() { rm -rf -- "$work_dir"; }
trap cleanup EXIT
systemctl stop auto-photo-ingest.timer
for _ in {1..60}; do
  systemctl is-active --quiet auto-photo-ingest.service || break
  sleep 1
done
systemctl is-active --quiet auto-photo-ingest.service && { echo "Worker is still active; data unchanged" >&2; exit 1; }
cat > "$work_dir/source.tgz.b64" <<'PAYLOAD'

PAYLOAD
base64 -d "$work_dir/source.tgz.b64" > "$work_dir/source.tgz"
printf '%s  %s
' '7641058e9d5394ee4a54375dee354626d10146351d559dbd609f1bc90241a72a' "$work_dir/source.tgz" | sha256sum -c -
mkdir "$work_dir/source"
tar -xzf "$work_dir/source.tgz" -C "$work_dir/source"
/opt/auto-photo-ingest/venv/bin/python -m pip install --no-deps --force-reinstall "$work_dir/source"
runuser -u auto-photo-ingest -- /opt/auto-photo-ingest/venv/bin/auto-photo-ingest init --data-dir /var/lib/auto-photo-ingest
runuser -u auto-photo-ingest -- /opt/auto-photo-ingest/venv/bin/auto-photo-ingest screen-plan --data-dir /var/lib/auto-photo-ingest
runuser -u auto-photo-ingest -- /opt/auto-photo-ingest/venv/bin/auto-photo-ingest screen-export --data-dir /var/lib/auto-photo-ingest --output-dir /var/lib/auto-photo-ingest/screening
systemctl start auto-photo-ingest.service
systemctl enable --now auto-photo-ingest.timer
printf 'UPGRADE=OK
VERSION='
/opt/auto-photo-ingest/venv/bin/python -c "from importlib.metadata import version; print(version('auto-photo-ingest'))"
printf 'COUNTS=
'
/opt/auto-photo-ingest/venv/bin/python - <<'PY2'
import json, sqlite3
root = '/var/lib/auto-photo-ingest'
db = sqlite3.connect(root + '/catalogue.sqlite3')
print('photos:', db.execute('select count(*) from assets').fetchone()[0])
print('vehicle_groups:', db.execute('select count(*) from vehicle_candidates').fetchone()[0])
print('grouped_photos:', db.execute('select count(*) from candidate_assets').fetchone()[0])
print('queues:', json.load(open(root + '/screening/summary.json', encoding='utf-8')))
PY2
printf 'TIMER='
systemctl is-active auto-photo-ingest.timer
